'use strict';
const V=VersionSafety;
statusNames.superseded='已被更新记录替代';
document.querySelector('.demo-banner').textContent='业务流程演示 V3 · 合成材料与模拟AI；已加入版本、效果更新与参考撤销校验。非真实AI或生产权限验证。';
function syncEdits(r){if(!r||r.owner!==user())return false;const body=$('#output'),title=$('#final-title');if(!body)return false;const changed=V.commit(r,body.value,title?title.value:r.title);if(changed){persist();notify('已先保存当前编辑为第 '+r.version+' 版，原评价待重新核对。');}return changed;}
saveVersion=function(content,why){if(!current)return;V.commit(current,content,current.title);current.lastChange=why;persist();renderResult();};
const previousRun=run;
run=async function(input,parent=null){if(busy)return;const resolved=refsFor(input),check=V.validateReferences(resolved,allSources());if(check.unavailable.length){show('result');$('#result-page').innerHTML='<div class="notice blocked"><h1>参考资格已变化</h1><p>以下参考已撤销、被替代或当前不可用，不会继续发送到模拟执行：</p><ul>'+check.unavailable.map(s=>'<li>'+esc(s.title||s.id)+'</li>').join('')+'</ul><p class="muted">历史来源记录保留；新一轮必须移除这些参考。</p><button id="remove-stale-refs" class="button primary">移除失效参考并重试</button></div>';$('#remove-stale-refs').onclick=()=>run({...input,parentSources:check.accepted.length?check.accepted:undefined},parent);return;}
const prior=parent?V.snapshot(parent):null,oldIds=new Set(db.records.map(r=>r.id));const account=$('#identity'),biz=$('#business');account.disabled=true;biz.disabled=true;
try{await previousRun({...input,parentSources:check.accepted},parent);if(!current)return;const changed=parent?current===parent&&current.version>prior.version:!oldIds.has(current.id);if(!changed)return;if(parent&&current.versions?.length){const last=current.versions[current.versions.length-1];Object.assign(last,prior);}
if(input.operation==='evaluate'){if(prior)current.title=prior.title;current.stage='assessment';current.operation='evaluate';current.content=input.material;current.assessment=F.compose(input,check.accepted).assessment;current.assessmentText=input.material;current.assessmentVersion=current.version;current.assessmentStatus='current';}else{current.stage='final';current.assessmentVersion=prior?.assessmentVersion??null;current.assessmentStatus=current.assessment?'stale':'not_assessed';}persist();renderResult();}finally{account.disabled=false;biz.disabled=false;}}
const previousAssessment=assessment;
assessment=function(a){if(current&&a===current.assessment&&!V.assessmentCurrent(current))return '<div class="notice"><strong>当前版本待重新评估</strong><p>这份评价未绑定当前正文版本，不能沿用为本版结论。如有历史评价，将保留在下方版本记录中。</p></div>';return previousAssessment(a);};
sources=function(ss){return ss.map(s=>'<article class="source-card"><span class="tag">'+esc(sourceTypeNames[s.type]||'历史合成来源')+'</span><h3>'+esc(s.title)+'</h3><details><summary>查看来源与使用边界</summary><p>'+esc(s.text)+'</p><p>'+esc(s.locator)+'</p><p class="muted">'+esc(s.usage)+'</p></details><span class="tag">'+(s.referenceStatus==='needs_recheck'?'当前版本待核对':s.referenceStatus==='mock_used'?'模拟采用（非真实AI证据）':'已选择，未模拟采用')+'</span></article>').join('');};
issueHTML=function(r){const text=r.stage==='assessment'?(r.assessmentText||r.content):r.content;const issues=F.evidence(text,r.sources);return '<section class="sentence-evidence"><h2>逐句核对与来源</h2><p class="muted">本次已展示 '+issues.length+' / '+issues.length+' 句。全部为演示核对，不认证为吉利根原话。</p>'+issues.map((x,n)=>'<details class="issue"><summary>第 '+(n+1)+' 句 · '+esc(x.kind)+'</summary><blockquote>'+esc(x.fragment)+'</blockquote><p>'+esc(x.suggestion)+'</p>'+(x.sourceId?'<button class="button ghost" data-source="'+esc(x.sourceId)+'">查看核验的合成来源</button>':'<p class="muted">没有已核验对应来源，不挂候选课程作证据。</p>')+'<p class="muted">'+esc(x.source)+'</p></details>').join('')+'</section>';};
function currentFormInput(){return {business:business(),inputType,operation:$('#intent').value,material:$('#material').value.trim(),requirements:$('#requirements').value.trim(),retain:$('#retain').value.trim(),outputType:$('#output-type').value,scenario:$('#scenario').value};}
$('#task-form').onsubmit=e=>{e.preventDefault();const i=currentFormInput();if(i.operation==='rewrite'){const a=F.analyze(i);i.retain=i.retain||a.keep;i.prohibited=a.prohibited;}run(i);};
$('#open-knowledge').insertAdjacentHTML('afterend','<button class="button ghost" type="button" id="optional-boundaries" style="margin-left:8px">查看／调整改写边界</button>');
$('#optional-boundaries').onclick=()=>{const i=currentFormInput();if(!i.material){notify('先填写素材再查看改写边界。');return;}prepare({...i,operation:'rewrite'});};
const previousEffects=effectDialog;
effectDialog=function(r){syncEdits(r);previousEffects(r);const previous=db.reviews.find(x=>x.recordId===r.id&&x.sourceVersion===r.version&&x.status==='pending')||db.reviews.find(x=>x.recordId===r.id&&x.sourceVersion===r.version&&x.status==='approved');const latest=previous||db.reviews.find(x=>x.recordId===r.id&&x.sourceVersion===r.version);const values=latest?.effects;if(values){$('#effect-quality').checked=!!values.quality;$('#effect-viral').checked=!!values.viral;$('#effect-platform').value=values.platform||'';$('#effect-confirm').checked=!!values.confirmed;$('#effect-sales').value=values.sales||'unverified';$('#effect-note').value=values.note||'';}
$('#effects-title').textContent=previous?(admin()?'管理员补充／更新效果':'补充效果并提交审核'):(admin()?'直接纳入团队参考':'提交团队审核');$('#effects-fields').insertAdjacentHTML('beforeend','<p class="muted">补充效果不修改文案版本。新声明独立留档；成员更新审核通过前，原已审参考继续有效。</p>');
$('#effects-save').onclick=()=>{const effects={quality:$('#effect-quality').checked,viral:$('#effect-viral').checked,platform:$('#effect-platform').value,confirmed:$('#effect-confirm').checked,sales:$('#effect-sales').value,note:$('#effect-note').value,confirmer:user(),confirmedAt:new Date().toISOString()};const error=F.validateEffects(effects);if(error){$('#effects-error').textContent=error;return;}if(previous&&V.sameEffects(previous.effects,effects)){$('#effects-error').textContent='标记未变化，无需重复提交。';return;}const s=A.snapshot(r,user(),admin());s.effects=effects;s.sources=V.clone(r.sources);s.supersedes=previous?.id||null;s.submissionRevision=(latest?.submissionRevision||1)+(latest?1:0);if(previous?.status==='pending'){previous.status='superseded';previous.supersededBy=s.id;previous.events=(previous.events||[]).concat([{action:'pending_replaced',by:s.id,at:new Date().toISOString()}]);}db.reviews.unshift(s);V.supersede(db.reviews,s);persist();$('#effects-dialog').close();renderResult();notify(admin()?'效果声明已直接更新，旧审核记录保留。':'已提交效果补充，待审核；原已审声明暂不变。');};};
const previousOpenReview=openReview;
openReview=function(x){previousOpenReview(x);$('#review-detail').insertAdjacentHTML('beforeend','<p class="muted">效果声明修订 '+(x.submissionRevision||1)+(x.supersedes?' · 更新自既有声明':'')+'；文案版本 '+x.sourceVersion+'</p>');const approve=$('[data-decision="approved"]');if(approve){const original=approve.onclick;approve.onclick=()=>{original();V.supersede(db.reviews,x);persist();renderReviews();};}};
const previousRender=renderResult;
renderResult=function(){previousRender();const r=current;if(!r)return;const own=r.owner===user();if($('#final-title'))$('#final-title').readOnly=!own;
if($('#save-edit'))$('#save-edit').onclick=()=>{const changed=syncEdits(r);renderResult();if(!changed)notify('内容未变化，无需新增版本。');};
if($('#submit-team')){const button=$('#submit-team');button.disabled=false;const active=db.reviews.some(x=>x.recordId===r.id&&x.sourceVersion===r.version&&['approved','pending'].includes(x.status));button.textContent=active?(admin()?'补充／更新效果':'补充效果／查看提交'):(admin()?'直接纳入团队参考':'提交团队审核');button.onclick=()=>effectDialog(r);}
const download=$('#download');if(download){const original=download.onclick;download.onclick=()=>{syncEdits(r);original();renderResult();};}
if($('#revise')){const original=$('#revise').onclick;$('#revise').onclick=()=>{syncEdits(r);original();};}
if($('#rewrite-by-report'))$('#rewrite-by-report').onclick=()=>run({business:r.business,inputType:r.inputType,operation:'rewrite',material:r.assessmentText||r.content,retain:r.retain,requirements:r.requirements,parentSources:r.sources,scenario:'available'},r);
if(own&&r.stage!=='assessment'){$('#result-page .result-top').insertAdjacentHTML('afterend','<div class="button-row"><button id="reevaluate-current" class="button ghost">重新评估当前版本</button></div>');$('#reevaluate-current').onclick=()=>{syncEdits(r);run({business:r.business,inputType:r.inputType,operation:'evaluate',material:r.content,retain:r.retain,requirements:r.requirements,outputType:r.outputType,parentSources:r.sources,scenario:'available'},r);};}
};
let historyType='all';const previousHistory=renderHistory;
renderHistory=function(){previousHistory();const row=document.querySelector('#history-page .filter-row');if(!$('#history-content-type'))row.insertAdjacentHTML('beforeend','<label>记录类型<select id="history-content-type"><option value="all">全部记录</option><option value="assessment">评估报告</option><option value="final">终稿</option></select></label>');$('#history-content-type').value=historyType;$('#history-content-type').onchange=()=>{historyType=$('#history-content-type').value;renderHistory();};let visible=0;$$('#history-list .history-row').forEach(el=>{const id=el.querySelector('[data-open]')?.dataset.open,r=db.records.find(x=>x.id===id);if(!r)return;const type=r.stage==='assessment'||r.operation==='evaluate'?'assessment':'final';el.querySelector('h2').insertAdjacentHTML('afterend','<span class="tag">'+(type==='assessment'?'评估报告':'终稿')+'</span>');el.hidden=historyType!=='all'&&historyType!==type;if(!el.hidden)visible++;});$('#history-count').textContent='当前筛选 '+visible+' 条 · 报告与终稿分开标识 · 仅本地演示';};
